Action.ExecScriptExpression:
using System;
using System.Collections.Generic;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;

// 获取变量存储
VariableStore store = RealPlugin.Instance.GetVariableStore(false);

// ====== 读取变量 ======
string MMapID = store.GetScalarVariable("MMapID")?.Value?.ToString() ?? "";
string MWorldID = store.GetScalarVariable("MWorldID")?.Value?.ToString() ?? "";
string M木人ID = store.GetScalarVariable("M木人ID")?.Value?.ToString() ?? "";
string MVisitTime = store.GetScalarVariable("MVisitTime")?.Value?.ToString() ?? "";
string MRefreshTime = store.GetScalarVariable("MRefreshTime")?.Value?.ToString() ?? "unknown";

// ====== 读取 Mdao ======
string MdaoValue = store.GetScalarVariable("Mdao")?.Value?.ToString() ?? "";

// ====== 解析记录 ======
List<string[]> records = new List<string[]>();
if (!string.IsNullOrEmpty(MdaoValue))
{
    foreach (string row in MdaoValue.Split(';'))
    {
        if (!string.IsNullOrEmpty(row)) records.Add(row.Split(','));
    }
}

// ====== 查找匹配 ======
bool found = false;
for (int i = 0; i < records.Count; i++)
{
    string[] r = records[i];
    if (r.Length >= 5 && r[0] == MMapID && r[1] == MWorldID && r[2] == M木人ID)
    {
        MRefreshTime = r[3];
        r[4] = MVisitTime;
        found = true;
        break;
    }
}

// ====== 未找到则新增 ======
if (!found)
{
    records.Add(new string[] { MMapID, MWorldID, M木人ID, "unknown", MVisitTime });
    MRefreshTime = "unknown";
}

// ====== 构建并写回 Mdao ======
string newMdaoValue = "";
for (int i = 0; i < records.Count; i++)
{
    if (i > 0) newMdaoValue += ";";
    newMdaoValue += string.Join(",", records[i]);
}

store.Scalar["Mdao"] = new VariableScalar
{
    Value = newMdaoValue,
    LastChanger = "Mata",
    LastChanged = DateTime.Now
};

// ====== 写回 MRefreshTime ======
store.Scalar["MRefreshTime"] = new VariableScalar
{
    Value = MRefreshTime,
    LastChanger = "Mata",
    LastChanged = DateTime.Now
};

// ====== 输出结果 ======
// RealPlugin.plug.InvokeNamedCallback("command", $"/e MRefreshTime = {MRefreshTime}");

using System;
using System.Collections.Generic;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.Utilities;

const ulong ListStartOffset = 0x90;
const ulong ListEndOffset = 0x98;
const ulong FateIdOffset = 0x18;
const ulong TimeStampOffset = 0x20;
const string SigPattern = "48 89 01 48 8B 3D ?? ?? ?? ?? 48 8B 87";
const int RelOffsetIndex = 6;

static VariableStore _globalVarStore = RealPlugin.Instance.GetVariableStore(false);

try
{
    var baseAddr = Memory.XivBaseAddress;
    if (baseAddr == IntPtr.Zero)
    {
        RealPlugin.plug.InvokeNamedCallback("command", "/e 错误：获取游戏基地址失败");
        return;
    }

    byte[] moduleData = Memory.ReadModuleData(Memory.XivProc);
    if (moduleData == null || moduleData.Length == 0)
    {
        RealPlugin.plug.InvokeNamedCallback("command", "/e 错误：读取进程模块数据失败");
        return;
    }

    int? sigPos = Memory.ScanPoint(moduleData, SigPattern);
    if (sigPos == null)
    {
        RealPlugin.plug.InvokeNamedCallback("command", $"/e 错误：未匹配特征码 {SigPattern}");
        return;
    }

    int relValue = Memory.BytesToStructure<int>(moduleData, sigPos.Value + RelOffsetIndex);
    ulong managerPtr = (ulong)baseAddr + (ulong)sigPos.Value + (ulong)(RelOffsetIndex + 4) + (ulong)relValue;

    ulong managerBase = Memory.Read<ulong>(Memory.XivProcHandle, (IntPtr)managerPtr);
    if (managerBase == 0 || managerBase < 0x100000)
    {
        RealPlugin.plug.InvokeNamedCallback("command", "/e 错误：Fate管理器地址无效");
        return;
    }

    ulong listStart = Memory.Read<ulong>(Memory.XivProcHandle, (IntPtr)(managerBase + ListStartOffset));
    ulong listEnd = Memory.Read<ulong>(Memory.XivProcHandle, (IntPtr)(managerBase + ListEndOffset));
    if (listStart == 0 || listEnd == 0 || listStart >= listEnd) return;

    int count = (int)((listEnd - listStart) / 0x8);

    // ====== FateId 映射表 ======
    Dictionary<ushort, (string mapId, string position)> fateMap = new Dictionary<ushort, (string, string)>()
    {
        { 0x7B8, ("4E4", "北") },
        { 0x7B9, ("4E4", "南") },
        { 0x818, ("542", "北") },
        { 0x819, ("542", "南") }
    };

    // ====== 读取当前变量 ======
    string MMapID = _globalVarStore.GetScalarVariable("MMapID")?.Value?.ToString() ?? "";
    string MWorldID = _globalVarStore.GetScalarVariable("MWorldID")?.Value?.ToString() ?? "";
    string M木人ID = _globalVarStore.GetScalarVariable("M木人ID")?.Value?.ToString() ?? "";
    string MVisitTime = _globalVarStore.GetScalarVariable("MVisitTime")?.Value?.ToString() ?? "";

    for (int i = 0; i < count; i++)
    {
        ulong fateAddr = Memory.Read<ulong>(Memory.XivProcHandle, (IntPtr)(listStart + (ulong)i * 0x8));
        if (fateAddr == 0 || fateAddr < 0x100000) continue;

        ushort memFateId = Memory.Read<ushort>(Memory.XivProcHandle, (IntPtr)(fateAddr + FateIdOffset));

        if (fateMap.TryGetValue(memFateId, out var mapping))
        {
            // ====== 校验 MapID ======
            if (mapping.mapId != MMapID) continue;

            int timeStamp = Memory.Read<int>(Memory.XivProcHandle, (IntPtr)(fateAddr + TimeStampOffset));
            if (timeStamp <= 0) continue;

            // ====== 统一转成北罐时间（南罐减1803秒） ======
            long northTime = timeStamp;
            if (mapping.position == "南")
            {
                northTime = timeStamp - 1803;
            }

            string MRefreshTime = northTime.ToString();

            // ====== 写入 MRefreshTime（永远是北罐时间） ======
            _globalVarStore.Scalar["MRefreshTime"] = new VariableScalar
            {
                Value = MRefreshTime,
                LastChanger = "Mata",
                LastChanged = DateTime.Now
            };

            // ====== 更新 Mdao ======
            string MdaoValue = _globalVarStore.GetScalarVariable("Mdao")?.Value?.ToString() ?? "";

            List<string[]> records = new List<string[]>();
            if (!string.IsNullOrEmpty(MdaoValue))
            {
                foreach (string row in MdaoValue.Split(';'))
                {
                    if (!string.IsNullOrEmpty(row)) records.Add(row.Split(','));
                }
            }

            bool found = false;
            for (int j = 0; j < records.Count; j++)
            {
                string[] r = records[j];
                if (r.Length >= 5 && r[0] == MMapID && r[1] == MWorldID && r[2] == M木人ID)
                {
                    r[3] = MRefreshTime;
                    r[4] = MVisitTime;
                    found = true;
                    break;
                }
            }

            if (!found)
            {
                records.Add(new string[] { MMapID, MWorldID, M木人ID, MRefreshTime, MVisitTime });
            }

            string newMdaoValue = "";
            for (int j = 0; j < records.Count; j++)
            {
                if (j > 0) newMdaoValue += ";";
                newMdaoValue += string.Join(",", records[j]);
            }

            _globalVarStore.Scalar["Mdao"] = new VariableScalar
            {
                Value = newMdaoValue,
                LastChanger = "Mata",
                LastChanged = DateTime.Now
            };

            // ====== 输出结果 ======
            DateTime localTime = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc)
                .AddSeconds(timeStamp)
                .ToLocalTime();

            // RealPlugin.plug.InvokeNamedCallback("command", $"/e 检测到Fate {mapping.position}罐: MRefreshTime(北罐时间)={MRefreshTime} ({localTime:HH:mm:ss})");

            break;
        }
    }
}
catch (Exception ex)
{
    RealPlugin.plug.InvokeNamedCallback("command", $"/e 脚本执行异常：{ex.Message}");
}

